input.script:
// Set selector-0 to iPhone 15 Pro, selector-1 to iPhone 14 Pro, selector-2 to iPhone 14 Pro Max for a good comparison
var s0 = document.getElementById('selector-0');
var s1 = document.getElementById('selector-1');
var s2 = document.getElementById('selector-2');
s0.value = 'BxoBktn9'; // iPhone 15 Pro
s1.value = 'KYlix4hz'; // iPhone 14 Pro
s2.value = 'ponGukYT'; // iPhone 14 Pro Max
s0.dispatchEvent(new Event('change', { bubbles: true }));
s1.dispatchEvent(new Event('change', { bubbles: true }));
s2.dispatchEvent(new Event('change', { bubbles: true }));
return { s0: s0.value, s1: s1.value, s2: s2.value };

// Find the comparison data for iPhone 15 Pro and iPhone 14 Pro
// First, find price sections
var results = {};
var allElements = document.querySelectorAll('*');
var priceElements = [];
var chipElements = [];
allElements.forEach(function(el) {
  var text = (el.textContent || '').trim();
  // Look for chip names
  if (text === 'A16 Bionic' || text === 'A17 Pro' || text === 'A16' || text === 'A17') {
    if (el.children.length === 0) {
      chipElements.push({ text: text, className: el.className });
    }
  }
});
return { 
  chipElements: chipElements.slice(0, 10),
  url: window.location.href
};

// Find price and chip information on the page
var sections = document.querySelectorAll('.compare-row, [class*="compare"], [class*="section"]');
var result = { sections: [] };
sections.forEach(function(el, i) {
  if (i < 30) {
    var text = (el.textContent || '').trim().substring(0, 500);
    if (text.length > 5) {
      result.sections.push({ class: el.className.substring(0, 100), text: text });
    }
  }
});
return result;

// Find chip section
var sections = document.querySelectorAll('.compare-rowheader');
var result = [];
sections.forEach(function(el, i) {
  result.push({ idx: i, text: el.textContent.trim() });
});
return result;

// Find the Chip section and get its content
var chipSections = [];
var allSections = document.querySelectorAll('section, .compare-section, .backport-group');
allSections.forEach(function(sec) {
  var h = sec.querySelector('.compare-rowheader, h2, h3');
  if (h && h.textContent.trim() === 'Chip') {
    chipSections.push(sec.textContent.trim().substring(0, 2000));
  }
});

// Get rendered price
var dynamicPrice = document.querySelector('.dynamic-price-proxy');
var priceText = dynamicPrice ? dynamicPrice.textContent.trim().substring(0, 2000) : 'not found';

// Get all price-related elements
var allPrices = [];
document.querySelectorAll('[class*="price"], [class*="Price"]').forEach(function(el, i) {
  if (i < 20) {
    allPrices.push({ class: el.className.substring(0, 60), text: el.textContent.trim().substring(0, 300) });
  }
});

return { chipSections: chipSections, priceText: priceText, allPrices: allPrices };

// Find the Price section in the comparison
var priceSections = [];
var allSections = document.querySelectorAll('section, .compare-section, .backport-group, [class*="Price"]');
allSections.forEach(function(sec) {
  var text = sec.textContent.trim();
  if (text.startsWith('Price-Sticky') || text.includes('Price-Sticky')) {
    priceSections.push(text.substring(0, 3000));
  }
});

// Also look for all price-related text on the page
var priceTexts = [];
document.querySelectorAll('.compare-column').forEach(function(el, i) {
  var txt = el.textContent.trim();
  if (txt.match(/\$\d+|From \$|or \$/) && i < 30) {
    priceTexts.push({ idx: i, text: txt.substring(0, 500) });
  }
});

return { priceSections: priceSections, priceTexts: priceTexts };

// Check structured data for pricing
var data = __data();
return data;

// Look for any pricing info - check all script tags and other data
var scripts = document.querySelectorAll('script');
var priceData = [];
scripts.forEach(function(s, i) {
  var content = s.textContent || '';
  if (content.includes('iPhone 15 Pro') || content.includes('iPhone 14 Pro')) {
    if (content.match(/price|amount|currency/i) && content.length < 100000) {
      priceData.push({ idx: i, len: content.length, has15pro: content.includes('iphone-15-pro'), has14pro: content.includes('iphone-14-pro') });
    }
  }
});

// Also check window/shop data
var shop = window['shop-data'] || window['shop'] || window['prices'] || {};
var shopKeys = Object.keys(shop);

return { scripts: priceData, shopKeys: shopKeys, location: window.location.href };

// Find the visible Price section - look at the right context
// The actual page is structured with named groups
var namedGroups = document.querySelectorAll('[data-template-id]');
var result = [];
namedGroups.forEach(function(g, i) {
  result.push({ idx: i, tpl: g.getAttribute('data-template-id'), text: g.textContent.trim().substring(0, 1000) });
});

// Find elements with "authorized resellers" text
var resellers = [];
document.querySelectorAll('*').forEach(function(el) {
  if (el.children.length === 0 && (el.textContent.trim() === 'Available at authorized resellers' || el.textContent.trim() === '—')) {
    resellers.push({ tag: el.tagName, class: el.className.substring(0, 60), parent: el.parentElement ? el.parentElement.className.substring(0, 60) : null });
  }
});

return { namedGroups: result.slice(0, 5), resellersCount: resellers.length, resellersSample: resellers.slice(0, 5) };

// Get the actual rendered Price and Chip columns for the 3 selected models
// Looking for the visible columns - find the iPhone 15 Pro section first
var columns = document.querySelectorAll('.compare-section');
var result = { sections: [] };
columns.forEach(function(sec, i) {
  var text = sec.textContent.trim().substring(0, 200);
  if (i < 25) {
    result.sections.push({ idx: i, text: text.substring(0, 100) });
  }
});
return result;

// Find the Chip section by scrolling to it and return its content
var chipSection = document.querySelector('[data-section-index="12"]');
if (!chipSection) {
  // Find by content
  var sections = document.querySelectorAll('.compare-row');
  for (var i = 0; i < sections.length; i++) {
    if (sections[i].textContent.includes('Chip') && !sections[i].textContent.includes('Apple')) {
      chipSection = sections[i];
      break;
    }
  }
}

// Scroll chip section into view
if (chipSection) {
  chipSection.scrollIntoView({ behavior: 'instant', block: 'center' });
  return { found: true, content: chipSection.textContent.trim().substring(0, 1500) };
}
return { found: false };

// Scroll to the Price section to see what's there
var allRows = document.querySelectorAll('.compare-row, [class*="section"]');
var priceSection = null;
allRows.forEach(function(r) {
  var text = r.textContent.trim();
  if (text.startsWith('Price-Sticky') || text.startsWith('Starting at') || text.startsWith('From $') || text.includes('authorized resellers')) {
    if (r.textContent.length < 3000) {
      priceSection = r;
    }
  }
});

if (priceSection) {
  priceSection.scrollIntoView({ behavior: 'instant', block: 'center' });
  return { 
    priceContent: priceSection.textContent.trim().substring(0, 2000),
    className: priceSection.className.substring(0, 100)
  };
}
return { priceContent: 'not found' };

// Scroll to and capture the Chip section specifically
var allRows = document.querySelectorAll('[class*="section"]');
var chipSection = null;
allRows.forEach(function(r) {
  var header = r.querySelector('h2, h3, .compare-rowheader');
  if (header && header.textContent.trim() === 'Chip') {
    chipSection = r;
  }
});

if (chipSection) {
  chipSection.scrollIntoView({ behavior: 'instant', block: 'center' });
  return { 
    chipContent: chipSection.textContent.trim().substring(0, 2500),
    chipClass: chipSection.className.substring(0, 100)
  };
}
return { error: 'chip section not found' };

// Find the Price section
var allRows = document.querySelectorAll('section');
var priceSection = null;
allRows.forEach(function(r) {
  if (r.textContent.trim().startsWith('Price-Sticky') || r.className.includes('Price-Sticky')) {
    if (r.textContent.length < 4000) {
      priceSection = r;
    }
  }
});

if (priceSection) {
  priceSection.scrollIntoView({ behavior: 'instant', block: 'center' });
  return { 
    priceContent: priceSection.textContent.trim().substring(0, 2500),
    priceClass: priceSection.className.substring(0, 100)
  };
}
return { error: 'Price section not found' };
